import json,numpy as np
from PIL import Image,ImageDraw
s=json.load(open('/app/output/spec.json'))
def ray(c,u,v):
 T=np.array(s['cameras'][c]['cam2world_gl']); f=s['cameras'][c]['intrinsic_cv'][0][0]; return T[:3,3],T[:3,:3]@np.array([(u-160)/f,-(v-160)/f,-1])
def tri(a,b):
 c1,v1=ray(*a); c2,v2=ray(*b); x=np.linalg.lstsq(np.c_[v1,-v2],c2-c1,rcond=None)[0]; p1=c1+x[0]*v1; p2=c2+x[1]*v2; print(a,b,(p1+p2)/2,'err',np.linalg.norm(p1-p2))
